VALUES (530385, 'tt8772262', NULL, 'Midsommar', 'Midsommar', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/7LEI8ulZzO5gy9Ww2NVCrKmHeDZ.jpg', 'https://image.tmdb.org/t/p/original/aAM3cQmYGjjLQ24m0F0RWfjKQ57.jpg', 'Several friends travel to Sweden to study as anthropologists a summer festival that is held every ninety years in the remote hometown of one of them. What begins as a dream vacation in a place where the sun never sets, gradually turns into a dark nightmare as the mysterious inhabitants invite them to participate in their disturbing festive activities.', NULL, NULL, 20.4087, 7.14, 0, 1.53478859060402669e+02, '2026-07-15 12:01:52', '2026-11-17 02:21:28')
