VALUES (4922, 'tt0421715', NULL, 'The Curious Case of Benjamin Button', 'The Curious Case of Benjamin Button', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/26wEWZYt6yJkwRVkjcbwJEFh9IS.jpg', 'https://image.tmdb.org/t/p/original/2fswjyrY3GEzeoVn6mF8pNeNcgf.jpg', 'Born under unusual circumstances, Benjamin Button springs into being as an elderly man in a New Orleans nursing home and ages in reverse. Twelve years after his birth, he meets Daisy, a child who flits in and out of his life as she grows up to be a dancer. Though he has all sorts of unusual adventures over the course of his life, it is his relationship with Daisy, and the hope that they will come together at the right time, that drives Benjamin forward.', NULL, NULL, 11.3347, 7.607, 0, 1.82371428571428566e+01, '2026-07-15 12:01:52', '2026-11-17 02:21:28')
