VALUES (16136, 'tt0104573', NULL, 'Juice', 'Juice', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/hfXFPMhNjLnCugBHMN0nrtKW7Ra.jpg', 'https://image.tmdb.org/t/p/original/54xcERdFHlRny2FJ9NC4koForkR.jpg', 'Four Harlem friends -- Bishop, Q, Steel and Raheem -- dabble in petty crime, but they decide to go big by knocking off a convenience store. Bishop, the magnetic leader of the group, has the gun. But Q has different aspirations. He wants to be a DJ and happens to have a gig the night of the robbery. Unfortunately for him, Bishop isn''t willing to take no for answer in a game where everything''s for keeps.', NULL, NULL, 2.6501, 7.187, 0, 6.5225, '2026-07-29 20:51:09', '2026-11-17 02:21:28')
