VALUES (969681, 'tt22084616', NULL, 'Spider-Man: Brand New Day', 'Spider-Man: Brand New Day', 'movie', 2026, 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 'https://image.tmdb.org/t/p/original/7iwUUcKURMT7aKfCwMy6YnGtchD.jpg', 'Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.', NULL, NULL, 1167.3938, 7.9, 0, 6.135, '2026-08-03 14:31:56', '2026-11-17 02:21:28')
