VALUES (1567, 'tt0157016', NULL, 'I Stand Alone', 'Seul contre tous', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/4kMB2AAcDQ5diRuh7NTxuS90bx7.jpg', 'https://image.tmdb.org/t/p/original/AjE0eLKSJ8SmHg9aiTaSuX5Od6R.jpg', 'After completing jail time for beating up a man who tried to seduce his mentally-handicapped teenage daughter, the Butcher wants to start life anew. He institutionalizes his daughter and moves to the Lille suburbs with his mistress, who promises him a new butcher shop. Learning that she lied, the Butcher returns to Paris to find his daughter.', NULL, NULL, 1.5233, 7.4, 0, 1.19211111111111112e+01, '2026-08-09 02:29:31', '2026-11-17 02:21:28')
