VALUES (14242, 'tt0181288', NULL, 'American Movie', 'American Movie', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/y8dJgWr1HeW0RRxwANDWvgIXdsF.jpg', 'https://image.tmdb.org/t/p/original/bdSZ5SutGPvFPpRKZNcF1au6owe.jpg', 'American Movie documents the story of filmmaker Mark Borchardt, his mission, and his dream. Spanning over two years of intense struggle with his film, his family, financial decline, and spiritual crisis, American Movie is a portrayal of ambition, obsession, excess, and one man''s quest for the American Dream.', NULL, NULL, 1.2526, 7.542, 0, 12.27, '2026-08-11 22:09:33', '2026-11-17 02:21:28')
