VALUES (19426, 'tt0050783', NULL, 'Nights of Cabiria', 'Le notti di Cabiria', 'movie', 1957, 'https://image.tmdb.org/t/p/w500/xF4oCG3PLNbcrtPZbqB3BtkIbKg.jpg', 'https://image.tmdb.org/t/p/original/9yepEBnQNcKzWWyHdUiX8Mnqc6U.jpg', 'Rome, 1957. A woman, Cabiria, is robbed and left to drown by her boyfriend, Giorgio. Rescued, she resumes her life and tries her best to find happiness in a cynical world. Even when she thinks her struggles are over and she has found happiness and contentment, things may not be what they seem.', NULL, NULL, 2.1459, 8.0, 0, 2.01, '2026-09-01 03:44:37', '2026-11-17 02:21:28')
